/**
 * Browser coverage for the reminder controls on an invoice (the "disable payment reminders" checkbox and
 * the client notice in invoices/view_sumex.php). The reminders themselves are generated by
 * Invoices/Cron::reminders, covered by tests/Feature/Invoices/CronRemindersFeatureTest.php.
 *
 * Not covered, because the application does not do it yet: nothing passes $invoice_reminders to the view,
 * so the history panel never renders, and nothing reads the posted invoice_disable_reminders, so ticking the
 * box is not saved.
 */

import { test, expect } from '../test.js';
import { createInvoice } from '../support/fixtures.js';
import { dbExec, dbInsert } from '../support/db.js';

/** Create an invoice with a sumex row: its sumex_id is what selects the view that renders reminders. */
async function invoiceWithReminderView(page) {
  const invoice = await createInvoice(page);
  dbInsert('ip_invoice_sumex', {
    sumex_invoice: invoice.id,
    sumex_reason: 0,
    sumex_diagnosis: '',
    sumex_observations: '',
    sumex_treatmentstart: '2026-01-01',
    sumex_treatmentend: '2026-01-02',
    sumex_casedate: '2026-01-01',
  });

  return invoice;
}

const box = (page) => page.locator('#invoice_disable_reminders');
const clientNotice = (page) => box(page).locator('xpath=ancestor::div[contains(@class,"invoice-properties")]').locator('.help-block');

test.describe('Invoice reminders — view', () => {
  test('it offers the disable-reminders checkbox, unticked by default', async ({ page }) => {
    /* Arrange */
    const invoice = await invoiceWithReminderView(page);

    /* Act */
    await page.goto(`/invoices/view/${invoice.id}`);

    /* Assert */
    await expect(box(page)).toBeVisible();
    await expect(box(page)).not.toBeChecked();
  });

  test('it shows the checkbox ticked when the invoice has reminders disabled', async ({ page }) => {
    /* Arrange */
    const invoice = await invoiceWithReminderView(page);
    dbExec(`UPDATE ip_invoices SET invoice_disable_reminders = 1 WHERE invoice_id = ${invoice.id}`);

    /* Act */
    await page.goto(`/invoices/view/${invoice.id}`);

    /* Assert */
    await expect(box(page)).toBeChecked();
  });

  test('it tells the user when the client has disabled reminders', async ({ page }) => {
    /* Arrange */
    const invoice = await invoiceWithReminderView(page);
    dbExec(`UPDATE ip_clients SET client_disable_reminders = 1 WHERE client_id = ${invoice.clientId}`);

    /* Act */
    await page.goto(`/invoices/view/${invoice.id}`);

    /* Assert */
    await expect(clientNotice(page)).toBeVisible();
  });

  test('it shows no client notice while the client still allows reminders', async ({ page }) => {
    /* Arrange */
    const invoice = await invoiceWithReminderView(page);

    /* Act */
    await page.goto(`/invoices/view/${invoice.id}`);

    /* Assert */
    await expect(box(page)).toBeVisible();
    await expect(clientNotice(page)).toHaveCount(0);
  });
});
